const subscriptionRows = `-- name: SubscriptionRows :many
SELECT s.id, s.created_at, s.updated_at, s.starts_at, s.ends_at, s.swaps_used, s.swaps_allowance, s.status, s.auto_renew, s.account_id, s.plan_id, s.vehicle_id, s.amount_kobo, s.discount_code, s.discount_kobo, s.idempotency_key, s.list_price_kobo, s.payment_id, s.queued_plan_id, p.name AS plan_name, p.code AS plan_code, p.period AS plan_period, v.registration_plate AS vehicle_plate,
  a.display_name AS account_name, a.kura_id AS account_kura_id, a.owner_user_id
FROM mobility_subscription s JOIN mobility_plan p ON p.id = s.plan_id JOIN mobility_vehicle v ON v.id = s.vehicle_id
JOIN accounts_account a ON a.id = s.account_id
WHERE s.id = ANY($1::uuid[])
`

type SubscriptionRowsRow struct {
	ID             uuid.UUID
	CreatedAt      time.Time
	UpdatedAt      time.Time
	StartsAt       time.Time
	EndsAt         time.Time
	SwapsUsed      int32
	SwapsAllowance *int32
	Status         string
	AutoRenew      bool
	AccountID      uuid.UUID
	PlanID         uuid.UUID
	VehicleID      uuid.UUID
	AmountKobo     int64
	DiscountCode   string
	DiscountKobo   int64
	IdempotencyKey *string
	ListPriceKobo  int64
	PaymentID      *uuid.UUID
	QueuedPlanID   *uuid.UUID
	PlanName       string
	PlanCode       string
	PlanPeriod     string
	VehiclePlate   string
	AccountName    string
	AccountKuraID  string
	OwnerUserID    uuid.UUID
}

func (q *Queries) SubscriptionRows(ctx context.Context, ids []uuid.UUID) ([]SubscriptionRowsRow, error) {
	rows, err := q.db.Query(ctx, subscriptionRows, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SubscriptionRowsRow{}
	for rows.Next() {
		var i SubscriptionRowsRow
		if err := rows.Scan(
			&i.ID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StartsAt,
			&i.EndsAt,
			&i.SwapsUsed,
			&i.SwapsAllowance,
			&i.Status,
			&i.AutoRenew,
			&i.AccountID,
			&i.PlanID,
			&i.VehicleID,
			&i.AmountKobo,
			&i.DiscountCode,
			&i.DiscountKobo,
			&i.IdempotencyKey,
			&i.ListPriceKobo,
			&i.PaymentID,
			&i.QueuedPlanID,
			&i.PlanName,
			&i.PlanCode,
			&i.PlanPeriod,
			&i.VehiclePlate,
			&i.AccountName,
			&i.AccountKuraID,
			&i.OwnerUserID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
